#include "Amp.h"
#include <chrono>
#include <iostream>
#include <array>
int main(){constexpr int rate=48000,N=4800;constexpr double tau=6.283185307179586;std::cout<<"model,light,no_feedback,input,fundamental,thdn_pct,seconds,H2_dBc,H3_dBc,H4_dBc,H5_dBc,H6_dBc,H7_dBc,H8_dBc,H9_dBc,H10_dBc\n";for(int m=0;m<10;++m)for(int nf=0;nf<2;++nf)for(double a:{.001,.01,.1,.5})for(int light=0;light<2;++light){uhg::Engine e;e.controls.linkPower=false;e.controls.power=static_cast<uhg::PowerModel>(m);e.controls.powerOnly=true;e.controls.benchDirect=true;e.controls.disableFeedback=nf;e.controls.light=light;e.prepare(rate);for(int i=0;i<N*2;++i)e.process(a*std::sin(tau*1000*i/rate));std::array<double,N> y{};auto start=std::chrono::steady_clock::now();for(int i=0;i<N;++i)y[i]=e.process(a*std::sin(tau*1000*i/rate));double sec=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();double mean=0,ss=0;for(double v:y)mean+=v/N;for(double v:y)ss+=(v-mean)*(v-mean)/N;std::array<double,10> h{};for(int k=1;k<=10;++k){double re=0,im=0;for(int i=0;i<N;++i){re+=y[i]*std::cos(tau*1000*k*i/rate);im+=y[i]*std::sin(tau*1000*k*i/rate);}h[k-1]=std::hypot(re,im)*2/N;}double fund=std::max(h[0],1e-20);std::cout<<m<<','<<light<<','<<nf<<','<<a<<','<<h[0]<<','<<100*std::sqrt(std::max(0.,2*ss-fund*fund))/fund<<','<<sec;for(int k=1;k<10;++k)std::cout<<','<<20*std::log10(std::max(h[k],1e-20)/fund);std::cout<<'\n';} }
